'use strict';
// ============================================================
//  C3 · index-loader 打包化 —— 生产期预打包脚本
//
//  读取 public/js/index-loader.js 中的 modulePaths，把全部模块源码
//  按加载顺序拼接为单个文件 public/js/index-bundle.js，加载时一次请求。
//  用法: node scripts/bundle-index-modules.js [--check]
//    - 默认: 生成 bundle（并打印大小与模块数）。
//    - --check: 只校验 bundle 是否与当前模块源码一致（CI 契约守卫用），
//      不一致时以非零退出（避免提交过期 bundle）。
//
//  该 bundle 由构建/CI 在打包前生成；开发期未生成时 loader 自动回退到
//  并行 XHR 逐模块加载。
// ============================================================
const fs = require('fs');
const path = require('path');

const appRoot = path.resolve(__dirname, '..');
const loaderPath = path.join(appRoot, 'public', 'js', 'index-loader.js');
const bundlePath = path.join(appRoot, 'public', 'js', 'index-bundle.js');
const BUNDLE_MARKER = '/*#MINERADIO_INDEX_BUNDLE*/';
const SOURCE_URL = '//# sourceURL=mineradio-index-bundle.js\n';

function readModulePaths(loaderSource) {
  const match = loaderSource.match(/const modulePaths = \[([\s\S]*?)\];/);
  if (!match) throw new Error('modulePaths not found in public/js/index-loader.js');
  return [...match[1].matchAll(/'([^']+)'/g)].map((m) => m[1]);
}

// 可供 quick-check 与测试复用：返回 { text, moduleCount, byteLength }。
function buildBundleIndexModuleText() {
  const loaderSource = fs.readFileSync(loaderPath, 'utf8');
  const modulePaths = readModulePaths(loaderSource);
  const parts = [];
  modulePaths.forEach((relPath, index) => {
    const fullPath = path.join(appRoot, 'public', relPath);
    const source = fs.readFileSync(fullPath, 'utf8');
    parts.push(
      '/* ===== [' + (index + 1) + '/' + modulePaths.length + '] ' + relPath + ' ===== */\n' +
      source
    );
  });
  const body = parts.join('\n');
  const head = BUNDLE_MARKER + '\n' +
    '/* Generated by scripts/bundle-index-modules.js. Modules: ' + modulePaths.length + '. */\n\n';
  return {
    text: head + body + '\n' + SOURCE_URL,
    moduleCount: modulePaths.length,
    byteLength: Buffer.byteLength(body)
  };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { buildBundleIndexModuleText, readModulePaths, BUNDLE_MARKER };
}

function main() {
  const checkOnly = process.argv.includes('--check');
  const { text, moduleCount, byteLength } = buildBundleIndexModuleText();

  if (checkOnly) {
    if (!fs.existsSync(bundlePath)) {
      console.error('index-bundle.js is missing. Run `node scripts/bundle-index-modules.js` (or `npm run bundle:index`).');
      process.exit(1);
    }
    const existing = fs.readFileSync(bundlePath, 'utf8');
    if (existing !== text) {
      console.error('index-bundle.js is stale: modules changed after the bundle was generated.');
      console.error('Run `node scripts/bundle-index-modules.js` (or `npm run bundle:index`) and commit the refreshed bundle.');
      process.exit(1);
    }
    console.log('[OK] index-bundle.js is fresh (' + moduleCount + ' modules, ' + (byteLength / 1024).toFixed(1) + ' KB).');
    return;
  }

  fs.writeFileSync(bundlePath, text, 'utf8');
  console.log('Wrote public/js/index-bundle.js (' + moduleCount + ' modules, ' + (byteLength / 1024).toFixed(1) + ' KB).');
}

// 仅当作为脚本直接执行（node scripts/bundle-index-modules.js）时运行 main，
// 被 quick-check / 测试 require 复用 buildBundleIndexModuleText 时不产生副作用。
if (typeof require !== 'undefined' && typeof module !== 'undefined' && require.main === module) {
  try {
    main();
  } catch (err) {
    console.error('bundle-index-modules failed:', err && err.message ? err.message : err);
    process.exit(1);
  }
}
